int main(void) {
    int n, a[40] = {1, 1};
    scanf("%d", &n);
    for (int i = 2; i < n; i++) a[i] = a[i-1] + a[i-2];
    for (int i = 0; i < n; i++) printf("%d%c", a[i], i + 1 == n ? '\n' : ' ');
    return 0;
}
